			}

			if (tcs == Waiting)
			{
				if (Interlocked.CompareExchange(ref _tcs, Running, Waiting) != Waiting)
				{
					continue;
				}

				return null;
			}

			if (tcs != Running)
			{
				return tcs.Task;
			}

			var newTcs = new TaskCompletionSource();

