			var tcs = _tcs;

			if (tcs == Running)
			{
				if (Interlocked.CompareExchange(ref _tcs, value: null, Running) != Running)
				{
					continue;
				}

				return;
			}

			Infra.Assert(tcs is not null && tcs != Waiting);

			if (Interlocked.CompareExchange(ref _tcs, value: null, tcs) != tcs)
