/// <summary>
	///     Determines whether the specified instance is disposable.
	/// </summary>
	/// <typeparam name="T">The type of the instance.</typeparam>
	/// <param name="instance">The instance to check.</param>
	/// <returns>
	///     <c>true</c> if the instance is <see cref="IDisposable" /> or <see cref="IAsyncDisposable" />; otherwise,
	///     <c>false</c>.
	/// </returns>

declarations.body:
{
		switch (instance)
		{
			case IDisposable disposable:
				disposable.Dispose();

				break;

			case IAsyncDisposable asyncDisposable:
				var valueTask = asyncDisposable.DisposeAsync();

				if (valueTask.IsFaulted || valueTask.IsCanceled)
				{
					valueTask.GetAwaiter().GetResult();
				}

				break;
		}
	}

