{
			var container = GetCurrentContainer();

			for (var i = 0; i < container.Count; i ++)
			{
				var (type, itemLazy) = container[i];

				if (type == typeof(T))
				{
					if (itemLazy is null)
					{
						container[i] = (type, lazy);
					}
					else
					{
						container.Add((type, lazy));
					}

					return true;
